#[tokio::test]
async fn enqueue_assigns_order_and_replays_only_the_exact_request() {
    let Some(mut fixture) = fixture(vec![SupervisorDirectiveCapability::Pause]).await else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let mut caller_timestamp = pause_directive(
        &fixture,
        "directive-caller-timestamp",
        "directive-key-caller-timestamp",
    );
    caller_timestamp.created_at = timestamp(fixture.now);
    assert!(matches!(
        fixture.directives.enqueue(caller_timestamp).await,
        Err(DirectiveStoreError::ClientCreationTimeForbidden)
    ));

    let first_request = pause_directive(&fixture, "directive-first", "directive-key-first");
    let first = fixture
        .directives
        .enqueue(first_request.clone())
        .await
        .expect("enqueue first directive");
    assert!(!first.idempotent_replay);
    assert_eq!(first.record.directive.sequence, 1);
    assert!(!first.record.directive.created_at.is_empty());

    let replay = fixture
        .directives
        .enqueue(first_request.clone())
        .await
        .expect("replay first directive");
    assert!(replay.idempotent_replay);
    assert_eq!(replay.record, first.record);

    let second = fixture
        .directives
        .enqueue(pause_directive(
            &fixture,
            "directive-second",
            "directive-key-second",
        ))
        .await
        .expect("enqueue second directive");
    assert_eq!(second.record.directive.sequence, 2);

    let mut changed = first_request;
    changed.rationale = "changed content".to_string();
    assert!(matches!(
        fixture.directives.enqueue(changed).await,
        Err(DirectiveStoreError::IdempotencyConflict)
    ));
}

