#[tokio::test]
async fn receipts_append_once_and_require_the_exact_directive_binding() {
    let Some(mut fixture) = fixture(vec![SupervisorDirectiveCapability::Pause]).await else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let directive = fixture
        .directives
        .enqueue(pause_directive(
            &fixture,
            "directive-receipt",
            "directive-key-receipt",
        ))
        .await
        .expect("enqueue directive for receipt")
        .record
        .directive;
    let receipt = receipt_for(&directive, SystemTime::now() + Duration::from_secs(1));
    let first = fixture
        .directives
        .record_receipt(receipt.clone())
        .await
        .expect("record exact receipt");
    assert!(!first.idempotent_replay);
    assert!(first.record.receipt_position > 0);

    let replay = fixture
        .directives
        .record_receipt(receipt.clone())
        .await
        .expect("replay exact receipt");
    assert!(replay.idempotent_replay);
    assert_eq!(replay.record, first.record);

    let mut changed_digest = receipt.clone();
    changed_digest.payload_digest = vec![9; 32];
    assert!(matches!(
        fixture.directives.record_receipt(changed_digest).await,
        Err(DirectiveStoreError::ReceiptMismatch)
    ));

    let mut cross_target = receipt.clone();
    cross_target.node_id = "node:other".to_string();
    assert!(matches!(
        fixture.directives.record_receipt(cross_target).await,
        Err(DirectiveStoreError::ReceiptMismatch)
    ));

    let mut unknown = receipt;
    unknown.directive_id = "directive-unknown".to_string();
    assert!(matches!(
        fixture.directives.record_receipt(unknown).await,
        Err(DirectiveStoreError::UnknownDirective)
    ));
}
